app.get("/openapi.json", (_req, res) => {
  res.json(openApiSpec);
});

app.get("/health", (_req, res) => {
  res.send("OK");
});

app.use((err: any, _req: express.Request, res: express.Response, _next: express.NextFunction) => {
  if (err?.status && Array.isArray(err?.errors)) {
    res.status(err.status).json({
      error: err.message ?? "Request validation failed",
      code: "REQUEST_VALIDATION_ERROR",
      details: err.errors,
    });
    return;
  }

  const status = Number(err?.status) || 500;
  logger.error({ err, status }, "Unhandled API error");
  res.status(status).json({ error: err?.message ?? "Internal Server Error" });
});

const server = http.createServer();

const gameServer = new Server({
  transport: new WebSocketTransport({
    server,
    pingInterval: 15_000,
    pingMaxRetries: 2,
  }),
  express: (colyseusApp) => {
    // Colyseus default routes (e.g. /matchmake/*) are registered after this callback.
    // Only forward known API paths to Express so Colyseus can handle its own endpoints.
    colyseusApp.use((req, res, next) => {
      const path = req.path ?? "";
      const isApiRoute = path === "/api" || path.startsWith("/api/");
      const isAvatarRoute = path.startsWith("/avatars/");
      if (isApiRoute || isAvatarRoute || path === "/health" || path === "/openapi.json") {
        app(req, res, next);
        return;
      }
      next();
    });
  },
});

gameServer.define("lobby", LobbyRoom);
gameServer.define("poker", PokerRoom);

let recoveryInterval: NodeJS.Timeout | null = null;
let leaderboardInterval: NodeJS.Timeout | null = null;
let eventLoopLagInterval: NodeJS.Timeout | null = null;
let shuttingDown = false;

async function shutdown(reason: string, exitCode: number = 0) {
  if (shuttingDown) return;
  shuttingDown = true;
  logger.info({ reason }, "Shutdown started");

  if (recoveryInterval) {
    clearInterval(recoveryInterval);
    recoveryInterval = null;
  }
  if (leaderboardInterval) {
    clearInterval(leaderboardInterval);
    leaderboardInterval = null;
  }
  if (eventLoopLagInterval) {
    clearInterval(eventLoopLagInterval);
    eventLoopLagInterval = null;
  }

  try {
    await gameServer.gracefullyShutdown(false);
  } catch (err) {
    logger.error({ err }, "Failed to gracefully shutdown Colyseus");
  }

  await new Promise<void>((resolve) => {
    server.close(() => resolve());
  });

  try {
    await disconnectPrisma();
  } catch (err) {
    logger.error({ err }, "Failed to disconnect Prisma");
  }

  logger.info({ reason }, "Shutdown complete");
  process.exit(exitCode);
}

async function start() {
  await gameServer.listen(port);
  logger.info({ port, nodeEnv: env.NODE_ENV }, "Server listening (Express + Colyseus)");

  recoveryInterval = setInterval(() => {
    RecoveryService.reconcileAbandonedBalances().catch((err) => {
      logger.error({ err }, "Periodic recovery job failed");
    });
  }, 60 * 60 * 1000);

  if (isLeaderboardEnabled()) {
    void recomputeLeaderboardSafely();
    leaderboardInterval = setInterval(() => {
      void recomputeLeaderboardSafely();
    }, 60 * 60 * 1000);
  }

  const eventLoopHistogram = monitorEventLoopDelay({ resolution: 10 });
  eventLoopHistogram.enable();
  eventLoopLagInterval = setInterval(() => {
    const meanMs = eventLoopHistogram.mean / 1e6;
    if (meanMs > 50) {
      logger.warn({ eventLoopLagMs: Math.round(meanMs * 100) / 100 }, "EVENT_LOOP_LAG");
    }
  }, 5000);
}

void start().catch((err) => {
  logger.error({ err }, "Failed to start server");
  void shutdown("startup_error", 1);
});

server.on("error", (err) => {
  logger.error({ err }, "HTTP server error");
  void shutdown("server_error", 1);
});

process.once("SIGTERM", () => {
  void shutdown("SIGTERM");
});

process.once("SIGINT", () => {
  void shutdown("SIGINT");
});

process.once("uncaughtException", (err) => {
  logger.error({ err }, "Uncaught exception");
  void shutdown("uncaught_exception", 1);
});

process.once("unhandledRejection", (reason) => {
  logger.error({ reason }, "Unhandled rejection");
  void shutdown("unhandled_rejection", 1);
});

import { nanoid } from "nanoid";
import type { PrismaClient } from "@prisma/client";
import type { AwardGrant } from "../awards/types.js";
import { awardService } from "../awards/AwardService.js";
import { evaluateLessonAwards } from "../awards/evaluateLessonAwards.js";
import { gradeStep, validateActionAnswer } from "./grading/LessonGradingEngine.js";
import { normalizeGradingSpec } from "./grading/normalizeGradingSpec.js";
import { updateMasteryForStep } from "./MasteryService.js";
import { computeCurrentStepIndex, scorePctFromCounts } from "./attemptHelpers.js";
import { asObject } from "./utils/objectHelpers.js";
import type {
  GhostAttemptSummary,
  SubmitResponseDto,
  SubmitFeedbackDto,
  StartAttemptResponseDto,
} from "./types.js";

const SUPPORTED_GRADING_VERSION = 1;

type AttemptWithMeta = {
  id: string;
  lessonId: string;
  status: string;
  startedAt: Date;
  completedAt: Date | null;
  scorePct: number | null;
  summaryJson?: unknown;
  currentStepIndex?: number;
  submittedStepCount?: number;
  steps?: Array<{ stepId: string; feedbackJson: unknown; submittedAt: Date | null }>;
};

export type StartAttemptResult =
  | { ok: true; body: StartAttemptResponseDto; status: 200 | 201 }
  | { ok: false; error: "LESSON_NOT_FOUND"; status: 404; message: string };

const SUBMIT_ERROR_MESSAGES: Record<string, string> = {
  ATTEMPT_NOT_FOUND: "Attempt not found",
  STEP_NOT_FOUND: "Step not found",
  UNSUPPORTED_GRADING_VERSION: "Unsupported grading version for step",
  INVALID_ANSWER: "Invalid answer payload for this step type",
};

export type SubmitResult =
  | { ok: true; body: SubmitResponseDto }
  | {
      ok: false;
      error: keyof typeof SUBMIT_ERROR_MESSAGES;
      status: 404 | 422 | 400;
      message: string;
    };

export async function startOrResumeAttempt(
  prisma: PrismaClient,
  lessonId: string,
  userId: string,
): Promise<StartAttemptResult> {
  const lesson = await prisma.lesson.findUnique({
    where: { id: lessonId },
    select: {
      id: true,
      status: true,
      steps: { orderBy: { sequence: "asc" }, select: { id: true, sequence: true } },
    },
  });
  if (!lesson || lesson.status !== "PUBLISHED") {
    return { ok: false, error: "LESSON_NOT_FOUND", status: 404, message: "Lesson not found" };
  }

  const existing = await prisma.lessonAttempt.findFirst({
    where: { lessonId, userId, status: "IN_PROGRESS" },
    orderBy: { startedAt: "desc" },
    include: {
      steps: {
        include: { step: { select: { id: true, sequence: true } } },
      },
    },
  });

  if (existing) {
    const currentStepIndex = computeCurrentStepIndex(lesson.steps, existing.steps);
    const body = toAttemptResponseDto(
      { ...existing, currentStepIndex, submittedStepCount: existing.steps.length },
      true,
    );
    return { ok: true, body, status: 200 };
  }

  const created = await prisma.lessonAttempt.create({
    data: {
      id: `attempt_${nanoid(16)}`,
      lessonId,
      userId,
      status: "IN_PROGRESS",
    },
  });
  const body = toAttemptResponseDto(
    { ...created, currentStepIndex: 0, submittedStepCount: 0, steps: [] },
    false,
  );
  return { ok: true, body, status: 201 };
}

function toAttemptResponseDto(
  attempt: AttemptWithMeta,
  resumed: boolean,
): StartAttemptResponseDto {
  const steps = attempt.steps ?? [];
  const summary = asObject(attempt.summaryJson) as GhostAttemptSummary | null;
  return {
    attempt: {
      id: attempt.id,
      lessonId: attempt.lessonId,
      status: attempt.status,
      startedAt: attempt.startedAt.toISOString(),
      completedAt: attempt.completedAt?.toISOString() ?? null,
      scorePct: attempt.scorePct,
      summaryJson:
        summary &&
        typeof summary.matchedProCount === "number" &&
        typeof summary.totalDecisions === "number" &&
        typeof summary.accuracyPercent === "number"
          ? summary
          : null,
      currentStepIndex: attempt.currentStepIndex ?? 0,
      submittedStepCount: attempt.submittedStepCount ?? 0,
      submittedSteps: steps.map((s) => ({
        stepId: s.stepId,
        feedback: asObject(s.feedbackJson),
        submittedAt: s.submittedAt?.toISOString() ?? null,
      })),
    },
    resumed,
  };
}

function actionKeyFromAnswer(stepType: string, answer: unknown): string | null {
  if (stepType !== "ACTION_STEP") return null;
  const obj = asObject(answer);
  if (!obj) return null;
  const t = typeof obj.type === "string" ? obj.type.toUpperCase() : "";
  if (t === "FOLD") return "fold";
  if (t === "CHECK") return "check";
  if (t === "CALL") return "call";
  if (t === "BET" || t === "RAISE") return "raise";
  if (t === "ALL_IN") return "all_in";
  return null;
}

function feedbackFromGrade(
  grade: ReturnType<typeof gradeStep>,
  submittedActionKey?: string | null,
): SubmitFeedbackDto {
  const feedback: SubmitFeedbackDto = {
    response: grade.response,
    followUpInstructorMessage: grade.followUp,
    isCorrect: grade.isCorrect,
    scoreDelta: grade.scoreDelta,
  };
  if (grade.evBb != null) feedback.evBb = grade.evBb;
  if (grade.takeaway != null) feedback.takeaway = grade.takeaway;
  if (grade.frequencyPerMonth != null) feedback.frequencyPerMonth = grade.frequencyPerMonth;
  if (grade.gradeBand != null) feedback.gradeBand = grade.gradeBand;
  if (submittedActionKey != null) feedback.submittedActionKey = submittedActionKey;
  return feedback;
}

export async function submitStep(
  prisma: PrismaClient,
  params: { lessonId: string; attemptId: string; stepId: string; userId: string; answer: unknown },
): Promise<SubmitResult> {
  const { lessonId, attemptId, stepId, userId, answer } = params;

  const [attempt, lesson, step] = await Promise.all([
    prisma.lessonAttempt.findFirst({
      where: { id: attemptId, lessonId, userId },
    }),
    prisma.lesson.findUnique({
      where: { id: lessonId },
      select: { moduleCode: true },
    }),
    prisma.lessonStep.findFirst({
      where: { id: stepId, lessonId },
      include: {
        options: true,
        concepts: { include: { concept: true } },
      },
    }),
  ]);

  if (!attempt) {
    return { ok: false, error: "ATTEMPT_NOT_FOUND", status: 404, message: SUBMIT_ERROR_MESSAGES.ATTEMPT_NOT_FOUND };
  }
  if (!step) {
    return { ok: false, error: "STEP_NOT_FOUND", status: 404, message: SUBMIT_ERROR_MESSAGES.STEP_NOT_FOUND };
  }
  if ((step.gradingVersion ?? 1) !== SUPPORTED_GRADING_VERSION) {
    return {
      ok: false,
      error: "UNSUPPORTED_GRADING_VERSION",
      status: 422,
      message: SUBMIT_ERROR_MESSAGES.UNSUPPORTED_GRADING_VERSION,
    };
  }
  if (!validateActionAnswer(step.type, answer)) {
    return { ok: false, error: "INVALID_ANSWER", status: 400, message: SUBMIT_ERROR_MESSAGES.INVALID_ANSWER };
  }

  const existingSubmission = await prisma.lessonAttemptStep.findUnique({
    where: { attemptId_stepId: { attemptId, stepId } },
  });

  const spec = normalizeGradingSpec(step.gradingSpecJson, step.followUpMessage);
  const grade = gradeStep(spec, step.type, answer);
  const submittedActionKey = actionKeyFromAnswer(step.type, answer);
  const feedback = feedbackFromGrade(grade, submittedActionKey);
  const conceptLinks = step.concepts.map((c) => ({
    conceptId: c.conceptId,
    weight: c.concept ? 1 : 1,
  }));

  const result = await prisma.$transaction(async (tx) => {
    if (existingSubmission) {
      await tx.lessonAttemptStep.update({
        where: { attemptId_stepId: { attemptId, stepId } },
        data: {
          submittedAnswerJson: answer as object,
          isCorrect: grade.isCorrect,
          feedbackJson: feedback as object,
          submittedAt: new Date(),
        },
      });
    } else {
      await tx.lessonAttemptStep.create({
        data: {
          id: `attempt_step_${nanoid(16)}`,
          attemptId,
          stepId,
          submittedAnswerJson: answer as object,
          isCorrect: grade.isCorrect,
          feedbackJson: feedback as object,
        },
      });

      await updateMasteryForStep(tx, {
        userId,
        conceptLinks: step.concepts.map((c) => ({ conceptId: c.conceptId, weight: c.weight })),
        isCorrect: grade.isCorrect,
      });
    }

    const [gradedTotal, gradedCorrect] = await Promise.all([
      tx.lessonAttemptStep.count({
        where: {
          attemptId,
          step: { type: { not: "INFO_STEP" } },
        },
      }),
      tx.lessonAttemptStep.count({
        where: {
          attemptId,
          isCorrect: true,
          step: { type: { not: "INFO_STEP" } },
        },
      }),
    ]);

    const requiredTotal = await tx.lessonStep.count({
      where: { lessonId, NOT: { type: "INFO_STEP" } },
    });
    const scorePct = scorePctFromCounts(gradedCorrect, gradedTotal);
    const isComplete = requiredTotal === 0 || gradedTotal >= requiredTotal;

    const isGhostLesson = lesson?.moduleCode === "MODULE_GHOST";
    const ghostSummary: GhostAttemptSummary | null =
      isComplete && isGhostLesson && requiredTotal > 0
        ? {
            matchedProCount: gradedCorrect,
            totalDecisions: requiredTotal,
            accuracyPercent: Math.round((gradedCorrect / requiredTotal) * 100),
          }
        : null;

    const updated = await tx.lessonAttempt.update({
      where: { id: attemptId },
      data: {
        scorePct,
        status: isComplete ? "COMPLETED" : attempt.status,
        completedAt: isComplete ? attempt.completedAt ?? new Date() : null,
        ...(ghostSummary && { summaryJson: ghostSummary as object }),
        masteryDeltaJson: { lastStepId: step.id, updatedAt: new Date().toISOString() },
      },
    });

    let awardsGranted: AwardGrant[] = [];
    if (isComplete) {
      const completedByLesson = await tx.lessonAttempt.groupBy({
        by: ["lessonId"],
        where: { userId, status: "COMPLETED" },
      });
      const completedLessonCount = completedByLesson.length;
      await tx.userCurriculumProgress.upsert({
        where: { userId },
        create: { userId, completedLessonsCount: completedLessonCount, updatedAt: new Date() },
        update: { completedLessonsCount: completedLessonCount, updatedAt: new Date() },
      });
      const incorrectCount = await tx.lessonAttemptStep.count({
        where: { attemptId, isCorrect: false },
      });
      const firstTry = incorrectCount === 0;
      const lessonRow = await tx.lesson.findUnique({
        where: { id: lessonId },
        select: { id: true, title: true },
      });
      if (lessonRow) {
        const candidates = evaluateLessonAwards({
          attempt: { id: updated.id, lessonId: updated.lessonId, scorePct },
          lesson: { id: lessonRow.id, title: lessonRow.title },
          completedLessonCount,
          firstTry,
        });
        const bulk = await awardService.bulkGrant(userId, candidates);
        awardsGranted = bulk.granted;
      }
    }

    const summary = ghostSummary;
    const attemptPayload = {
      id: updated.id,
      lessonId: updated.lessonId,
      status: updated.status,
      scorePct: updated.scorePct,
      ...(summary &&
        typeof summary.accuracyPercent === "number" && {
          summaryJson: summary,
        }),
    };
    return {
      feedback,
      attempt: attemptPayload,
      awardsGranted,
      gradingDebug: { stepType: step.type, gradingSpec: JSON.stringify(step.gradingSpecJson) },
    };
  });

  return {
    ok: true,
    body: {
      ...result,
      ...(result.awardsGranted.length > 0 && { awardsGranted: result.awardsGranted }),
    },
  };
}

/**
 * Project a minimal hand spec through a simple state machine and capture
 * snapshots before each hero decision. Produces TableSnapshotPayload-shaped
 * output for the lesson builder. sizePot is converted during projection using
 * current pot (not before).
 */

import { createHash } from "node:crypto";
import type { TableSnapshotPayload } from "@poker-champ/realtime-contract";
import type { MinimalHandSpec, SpecAction, Street } from "./minimalHandSpec.types.js";
import { BOARD_LENGTH_BY_STREET, STREET_ORDER } from "./minimalHandSpec.types.js";
export type HeroDecisionPoint = {
  snapshot: TableSnapshotPayload;
  expectedAction: string;
  sequence: number;
  street: string;
  board: string[];
  proActionAmountCents: number | null;
  beforeInstructorMessage?: string;
  followUpContent?: string;
};

const BB_TO_CENTS = 100;
const LESSON_HERO_USER_ID = "user_1";

type SeatState = {
  seat: number;
  position: string;
  name: string;
  stackCents: number;
  roundBetCents: number;
  committedCents: number;
  status: "ACTIVE" | "FOLDED" | "ALL_IN" | "OUT";
  isDealer: boolean;
  isSB: boolean;
  isBB: boolean;
};

type ProjectionState = {
  street: Street;
  potCents: number;
  roundCurrentBetCents: number;
  minRaiseCents: number;
  actionCount: number;
  board: string[];
  seats: SeatState[];
  dealerSeat: number;
  sbSeat: number;
  bbSeat: number;
  toActSeat: number;
  handId: string;
};

function initialSeats(spec: MinimalHandSpec): SeatState[] {
  const bbCents = Math.round(spec.blinds.bb * BB_TO_CENTS);
  const sbCents = Math.round(spec.blinds.sb * BB_TO_CENTS);
  const hasExplicitSB = spec.playersInfo.some((p) => p.position === "SB");
  const seats: SeatState[] = spec.playersInfo.map((p) => {
    const stackBB = spec.stacksBB?.[p.position] ?? spec.stacksBB?.[String(p.seat)] ?? spec.startingStacksBB;
    const stackCents = Math.round(stackBB * BB_TO_CENTS);
    const isDealer = p.position === "BTN";
    const isSB = p.position === "SB" || (spec.players === 2 && isDealer);
    const isBB = p.position === "BB";
    let roundBetCents = 0;
    let committedCents = 0;
    if (isSB) {
      roundBetCents = sbCents;
      committedCents = sbCents;
    }
    if (isBB) {
      roundBetCents = bbCents;
      committedCents = bbCents;
    }
    return {
      seat: p.seat,
      position: p.position,
      name: p.name ?? `Seat ${p.seat}`,
      stackCents,
      roundBetCents,
      committedCents,
      status: "ACTIVE",
      isDealer,
      isSB,
      isBB,
    };
  });
  return seats;
}

function getSeat(state: ProjectionState, seat: number): SeatState | undefined {
  return state.seats.find((s) => s.seat === seat);
}

function nextActiveSeat(state: ProjectionState, fromSeat: number): number | null {
  const seatIndices = state.seats.map((s) => s.seat).sort((a, b) => a - b);
  const n = seatIndices.length;
  const idx = seatIndices.indexOf(fromSeat);
  if (idx < 0) return null;
  for (let i = 1; i <= n; i++) {
    const nextSeat = seatIndices[(idx + i) % n]!;
    const s = getSeat(state, nextSeat);
    if (s && (s.status === "ACTIVE" || s.status === "ALL_IN") && s.stackCents > 0) return nextSeat;
  }
  return null;
}

/** First to act preflop: heads-up = BTN; 3+ players = seat left of BB (UTG). */
function firstToActPreflop(state: ProjectionState, playerCount: number): number {
  if (playerCount === 2) return state.dealerSeat;
  const utg = nextActiveSeat(state, state.bbSeat);
  return utg ?? state.dealerSeat;
}

function firstToActPostflop(state: ProjectionState): number | null {
  const seatIndices = state.seats.map((s) => s.seat).sort((a, b) => a - b);
  const dealerIdx = seatIndices.indexOf(state.dealerSeat);
  if (dealerIdx < 0) return null;
  const n = seatIndices.length;
  for (let i = 1; i <= n; i++) {
    const seat = seatIndices[(dealerIdx + i) % n]!;
    const s = getSeat(state, seat);
    if (s && (s.status === "ACTIVE" || s.status === "ALL_IN") && s.stackCents > 0) return seat;
  }
  return null;
}

/** On street transition: reveal board up to street, reset round bet and per-seat round contributions so call sizing is correct. */
function advanceStreet(state: ProjectionState, spec: MinimalHandSpec, nextStreet: Street, playerCount: number): void {
  state.street = nextStreet;
  state.roundCurrentBetCents = 0;
  state.minRaiseCents = state.potCents > 0 ? Math.round(spec.blinds.bb * BB_TO_CENTS) : 0;
  for (const s of state.seats) {
    s.roundBetCents = 0;
  }
  const len = BOARD_LENGTH_BY_STREET[nextStreet];
  state.board = spec.board.slice(0, len);
  const first = nextStreet === "PREFLOP" ? firstToActPreflop(state, playerCount) : firstToActPostflop(state);
  state.toActSeat = first ?? -1;
}

function isHeroDecision(spec: MinimalHandSpec, action: SpecAction): boolean {
  if (action.isHeroDecision === true) return true;
  return action.actorSeat === spec.heroSeat;
}

function actionOptionsForExpected(expectedAction: string): TableSnapshotPayload["hero"]["actionOptions"] {
  const u = expectedAction.toUpperCase();
  return {
    canFold: u === "FOLD",
    canCheck: u === "CHECK",
    canCall: u === "CALL",
    canBet: u === "BET",
    canRaise: u === "RAISE",
    canAllIn: u === "ALL_IN",
    primaryWagerAction: u === "BET" ? "BET" : u === "RAISE" ? "RAISE" : "NONE",
    callAmount: 0,
    minRaiseTo: undefined,
    maxRaiseTo: undefined,
  };
}

function buildSnapshot(
  state: ProjectionState,
  spec: MinimalHandSpec,
  stepId: string,
  expectedAction: string,
  seq: number,
): TableSnapshotPayload {
  const nowTs = Date.now();
  const tableId = "lesson-spec";
  const bbCents = Math.round(spec.blinds.bb * BB_TO_CENTS);
  const sbCents = Math.round(spec.blinds.sb * BB_TO_CENTS);

  const seats = state.seats.map((s) => ({
    seat: s.seat,
    occupied: true,
    userId: s.seat === spec.heroSeat ? LESSON_HERO_USER_ID : `user_${s.seat}`,
    isBot: s.seat !== spec.heroSeat,
    name: s.name,
    status: s.status,
    stackCents: s.stackCents,
    roundBetCents: s.roundBetCents,
    committedCents: s.committedCents,
    connected: true,
    disconnectDeadlineTs: 0,
    isDealer: s.isDealer,
    isToAct: state.toActSeat === s.seat,
  }));

  const hand = {
    handId: state.handId,
    handNumber: 1,
    street: state.street,
    dealerSeat: state.dealerSeat,
    sbSeat: state.sbSeat,
    bbSeat: state.bbSeat,
    toActSeat: state.toActSeat,
    actionCount: state.actionCount,
    roundCurrentBetCents: state.roundCurrentBetCents,
    minRaiseCents: state.minRaiseCents,
    potCents: state.potCents,
    board: [...state.board],
  };

  const payload: Omit<TableSnapshotPayload, "stateHash"> = {
    version: 1,
    snapshotId: stepId,
    snapshotSeq: seq,
    emittedAtTs: nowTs,
    serverTimeTs: nowTs,
    reason: "ACTION_ACCEPTED",
    table: {
      tableId,
      tableName: spec.lessonTitle,
      visibility: "PUBLIC",
      maxSeats: 9,
      smallBlindCents: sbCents,
      bigBlindCents: bbCents,
      minBuyInCents: bbCents * 20,
      maxBuyInCents: bbCents * 200,
      showStats: true,
    },
    hand,
    seats,
    hero: {
      userId: LESSON_HERO_USER_ID,
      youAreSeated: true,
      seat: spec.heroSeat,
      holeCards: [...spec.heroHoleCards],
      actionOptions: actionOptionsForExpected(expectedAction),
    },
  };

  const stateHash = createHash("sha1").update(JSON.stringify(payload)).digest("hex");
  return { ...payload, stateHash };
}

export type ProjectSpecResult =
  | { ok: true; points: HeroDecisionPoint[]; maxStreetReached: Street; villainBarrelCount: number; totalActionCount: number }
  | { ok: false; error: string };

export function projectSpecToSnapshots(spec: MinimalHandSpec): ProjectSpecResult {
  const seats = initialSeats(spec);
  const dealerSeat = seats.find((s) => s.isDealer)?.seat ?? seats[0]!.seat;
  const sbSeat = seats.find((s) => s.isSB)?.seat ?? -1;
  const bbSeat = seats.find((s) => s.isBB)?.seat ?? -1;
  const potCents = Math.round((spec.blinds.sb + spec.blinds.bb) * BB_TO_CENTS);

  const state: ProjectionState = {
    street: "PREFLOP",
    potCents,
    roundCurrentBetCents: Math.round(spec.blinds.bb * BB_TO_CENTS),
    minRaiseCents: Math.round(spec.blinds.bb * BB_TO_CENTS),
    actionCount: 0,
    board: [],
    seats,
    dealerSeat,
    sbSeat,
    bbSeat,
    toActSeat: -1,
    handId: `spec_${Date.now()}`,
  };
  state.toActSeat = firstToActPreflop(state, spec.players);

  const points: HeroDecisionPoint[] = [];
  let stepSeq = 0;
  const villainBetsByStreet = new Set<string>();

  for (let i = 0; i < spec.actions.length; i++) {
    const action = spec.actions[i]!;

    if (state.street !== action.street) {
      if (STREET_ORDER.indexOf(action.street) < STREET_ORDER.indexOf(state.street)) {
        return { ok: false, error: `Action ${i + 1}: street ${action.street} is before current ${state.street}` };
      }
      advanceStreet(state, spec, action.street, spec.players);
    }

    if (state.toActSeat !== action.actorSeat) {
      return { ok: false, error: `Action ${i + 1}: expected toActSeat ${state.toActSeat}, got actorSeat ${action.actorSeat}` };
    }

    const actor = getSeat(state, action.actorSeat);
    if (!actor) return { ok: false, error: `Action ${i + 1}: seat ${action.actorSeat} not found` };
    if (actor.status !== "ACTIVE" && actor.status !== "ALL_IN") {
      return { ok: false, error: `Action ${i + 1}: seat ${action.actorSeat} is not active` };
    }

    if (isHeroDecision(spec, action)) {
      stepSeq++;
      const expectedAction = action.action;
      const snapshot = buildSnapshot(
        state,
        spec,
        `step_${String(stepSeq).padStart(2, "0")}`,
        expectedAction,
        stepSeq,
      );
      const proActionAmountCents =
        (action.action === "BET" || action.action === "RAISE" || action.action === "ALL_IN") && (action.sizeBB != null || action.sizePot != null)
          ? resolveAmountCents(state, spec, action)
          : null;
      points.push({
        snapshot,
        expectedAction,
        sequence: stepSeq,
        street: state.street,
        board: [...state.board],
        proActionAmountCents,
        beforeInstructorMessage: action.beforeInstructorMessage,
        followUpContent: action.followUpContent,
      });
    } else {
      if (action.actorSeat !== spec.heroSeat && (action.action === "BET" || action.action === "RAISE" || action.action === "ALL_IN")) {
        villainBetsByStreet.add(state.street);
      }
    }

    const amountCents = resolveAmountCents(state, spec, action);
    applyAction(state, action, amountCents);

    const nextIdx = i + 1;
    if (nextIdx < spec.actions.length) {
      const nextAction = spec.actions[nextIdx]!;
      if (nextAction.street !== state.street) {
        advanceStreet(state, spec, nextAction.street, spec.players);
      } else {
        const next = nextActiveSeat(state, action.actorSeat);
        state.toActSeat = next ?? firstToActPostflop(state) ?? -1;
      }
    } else {
      const next = nextActiveSeat(state, action.actorSeat);
      state.toActSeat = next ?? -1;
    }
  }

  const maxStreetReached = state.street;
  const villainBarrelCount = villainBetsByStreet.size;
  const totalActionCount = state.actionCount;

  return { ok: true, points, maxStreetReached, villainBarrelCount, totalActionCount };
}

/** sizePot uses pot before this action (state.potCents excludes the pending bet being matched). */
function resolveAmountCents(state: ProjectionState, spec: MinimalHandSpec, action: SpecAction): number {
  if (action.sizeBB != null) return Math.round(action.sizeBB * spec.blinds.bb * BB_TO_CENTS);
  if (action.sizePot != null) return Math.round(action.sizePot * state.potCents);
  if (action.action === "CALL") {
    const actor = getSeat(state, action.actorSeat);
    if (!actor) return 0;
    return Math.max(0, state.roundCurrentBetCents - actor.roundBetCents);
  }
  if (action.action === "CHECK" || action.action === "FOLD") return 0;
  if (action.action === "ALL_IN") {
    const actor = getSeat(state, action.actorSeat);
    return actor ? actor.stackCents : 0;
  }
  return 0;
}

function applyAction(state: ProjectionState, action: SpecAction, amountCents: number): void {
  const actor = getSeat(state, action.actorSeat);
  if (!actor) return;

  state.actionCount++;

  if (action.action === "FOLD") {
    actor.status = "FOLDED";
    return;
  }

  const toPut = Math.min(amountCents, actor.stackCents);
  actor.stackCents -= toPut;
  actor.roundBetCents += toPut;
  actor.committedCents += toPut;
  state.potCents += toPut;

  if (action.action === "BET" || action.action === "RAISE") {
    state.roundCurrentBetCents = actor.roundBetCents;
    state.minRaiseCents = Math.max(state.minRaiseCents, toPut);
  }
  if (actor.stackCents <= 0) actor.status = "ALL_IN";
}

/**
 * Structural validation for minimal hand spec.
 * Run before engine projection. Does not validate poker rules (engine does that).
 */

import type { MinimalHandSpec, SpecAction, Street } from "./minimalHandSpec.types.js";
import { STREET_ORDER, BOARD_LENGTH_BY_STREET } from "./minimalHandSpec.types.js";

const SUPPORTED_SPEC_VERSION = 1;

export type ValidationError = { path?: string; message: string };

export function validateMinimalSpec(spec: unknown): ValidationError[] {
  const errs: ValidationError[] = [];

  if (!spec || typeof spec !== "object") {
    return [{ message: "Spec must be an object" }];
  }

  const s = spec as Record<string, unknown>;

  if (s.specVersion !== SUPPORTED_SPEC_VERSION) {
    errs.push({ path: "specVersion", message: `Unsupported specVersion: ${s.specVersion}. Supported: ${SUPPORTED_SPEC_VERSION}` });
  }
  if (typeof s.lessonTitle !== "string" || !s.lessonTitle.trim()) {
    errs.push({ path: "lessonTitle", message: "lessonTitle is required and must be non-empty" });
  }
  if (typeof s.players !== "number" || s.players < 2 || s.players > 9) {
    errs.push({ path: "players", message: "players must be 2–9" });
  }

  const playersInfo = s.playersInfo;
  if (!Array.isArray(playersInfo) || playersInfo.length !== (s.players as number)) {
    errs.push({ path: "playersInfo", message: `playersInfo must be an array of length ${s.players}` });
  } else {
    const seats = new Set<number>();
    const positions = new Set<string>();
    for (let i = 0; i < playersInfo.length; i++) {
      const p = playersInfo[i] as Record<string, unknown>;
      if (typeof p?.seat !== "number" || p.seat < 1 || p.seat > 9) {
        errs.push({ path: `playersInfo[${i}].seat`, message: "seat must be 1–9" });
      } else {
        if (seats.has(p.seat)) errs.push({ path: `playersInfo[${i}].seat`, message: "duplicate seat" });
        seats.add(p.seat);
      }
      if (typeof p?.position !== "string") {
        errs.push({ path: `playersInfo[${i}].position`, message: "position is required" });
      } else if (positions.has(p.position)) {
        errs.push({ path: `playersInfo[${i}].position`, message: "duplicate position" });
      } else {
        positions.add(p.position);
      }
    }

    const heroSeat = s.heroSeat;
    if (typeof heroSeat !== "number") {
      errs.push({ path: "heroSeat", message: "heroSeat is required" });
    } else if (!seats.has(heroSeat)) {
      errs.push({ path: "heroSeat", message: "heroSeat must appear exactly once in playersInfo" });
    } else {
      const heroCount = playersInfo.filter((p: { seat: number }) => p.seat === heroSeat).length;
      if (heroCount !== 1) {
        errs.push({ path: "heroSeat", message: "heroSeat must appear exactly once in playersInfo" });
      }
    }
  }

  const blinds = s.blinds;
  if (!blinds || typeof blinds !== "object") {
    errs.push({ path: "blinds", message: "blinds is required" });
  } else {
    const b = blinds as Record<string, unknown>;
    if (typeof b.bb !== "number" || b.bb <= 0) errs.push({ path: "blinds.bb", message: "blinds.bb must be > 0" });
    if (typeof b.sb !== "number" || b.sb <= 0) errs.push({ path: "blinds.sb", message: "blinds.sb must be > 0" });
    if (typeof b.sb === "number" && typeof b.bb === "number" && b.sb >= b.bb) {
      errs.push({ path: "blinds", message: "blinds.sb must be < blinds.bb" });
    }
  }

  if (typeof s.startingStacksBB !== "number" || s.startingStacksBB < 1) {
    errs.push({ path: "startingStacksBB", message: "startingStacksBB must be >= 1" });
  }

  const heroHoleCards = s.heroHoleCards;
  if (!Array.isArray(heroHoleCards) || heroHoleCards.length !== 2) {
    errs.push({ path: "heroHoleCards", message: "heroHoleCards must be exactly two cards" });
  } else {
    const cardSet = new Set(heroHoleCards as string[]);
    if (cardSet.size !== 2) errs.push({ path: "heroHoleCards", message: "heroHoleCards must be unique" });
  }

  const board = s.board;
  if (!Array.isArray(board) || board.length > 5) {
    errs.push({ path: "board", message: "board must be an array of 0–5 cards" });
  } else {
    const boardSet = new Set(board as string[]);
    if (boardSet.size !== board.length) errs.push({ path: "board", message: "board cards must be unique" });
  }

  const heroCards = new Set((heroHoleCards as string[]) || []);
  const boardCards = new Set((board as string[]) || []);
  for (const c of heroCards) {
    if (boardCards.has(c)) errs.push({ path: "board", message: "heroHoleCards and board must be disjoint" });
  }

  const actions = s.actions;
  if (!Array.isArray(actions) || actions.length < 1) {
    errs.push({ path: "actions", message: "actions must have at least one action" });
  } else if (actions.length > 40) {
    errs.push({ path: "actions", message: "actions must have at most 40 items" });
  } else {
    let prevStreet: Street | null = null;
    for (let i = 0; i < actions.length; i++) {
      const a = actions[i] as Record<string, unknown>;
      if (typeof a?.street !== "string" || !STREET_ORDER.includes(a.street as Street)) {
        errs.push({ path: `actions[${i}].street`, message: "street must be PREFLOP, FLOP, TURN, or RIVER" });
      }
      if (typeof a?.actorSeat !== "number" || a.actorSeat < 1 || a.actorSeat > 9) {
        errs.push({ path: `actions[${i}].actorSeat`, message: "actorSeat must be 1–9" });
      }
      const actionKind = a?.action as string;
      if (!["FOLD", "CHECK", "CALL", "BET", "RAISE", "ALL_IN"].includes(actionKind)) {
        errs.push({ path: `actions[${i}].action`, message: "action must be FOLD, CHECK, CALL, BET, RAISE, or ALL_IN" });
      }
      if ((a?.sizeBB != null && a?.sizePot != null)) {
        errs.push({ path: `actions[${i}]`, message: "only one of sizeBB or sizePot may be set" });
      }
      const street = prevStreet ?? (a.street as Street);
      if (prevStreet && STREET_ORDER.indexOf(a.street as Street) < STREET_ORDER.indexOf(prevStreet)) {
        errs.push({ path: `actions[${i}].street`, message: "actions must be sorted by street" });
      }
      prevStreet = a.street as Street;
    }

    const heroSeatVal = s.heroSeat as number;
    const heroDecisionCount = (actions as SpecAction[]).filter(
      (a) => a.isHeroDecision === true || a.actorSeat === heroSeatVal,
    ).length;
    if (heroDecisionCount < 1) {
      errs.push({ path: "actions", message: "at least one hero decision required (actorSeat === heroSeat or isHeroDecision: true)" });
    }
  }

  const maxStreetReached = maxStreetFromActions((actions as SpecAction[]) || []);
  if (maxStreetReached && Array.isArray(board)) {
    const requiredLen = BOARD_LENGTH_BY_STREET[maxStreetReached];
    if (board.length < requiredLen) {
      errs.push({ path: "board", message: `board length must be >= ${requiredLen} for street ${maxStreetReached}` });
    }
  }

  return errs;
}

function maxStreetFromActions(actions: SpecAction[]): Street | null {
  let max: Street | null = null;
  for (const a of actions) {
    if (!max || STREET_ORDER.indexOf(a.street) > STREET_ORDER.indexOf(max)) max = a.street;
  }
  return max;
}

export function validateMinimalSpecOrThrow(spec: unknown): asserts spec is MinimalHandSpec {
  const errs = validateMinimalSpec(spec);
  if (errs.length > 0) {
    const msg = errs.map((e) => `${e.path ?? "spec"}: ${e.message}`).join("; ");
    throw new Error(`Invalid spec: ${msg}`);
  }
}

